mapper.select:
        select * from Notice_Info_Close
        
            
                and id=#{params.id}
            
            
                and sourceId=#{params.sourceId}
            
            
                and sourceCode=#{params.sourceCode}
            
            
                and noticeInfoId=#{params.noticeInfoId}
            
            
                and noticeCloseTime=#{params.noticeCloseTime}
            
            
                and noticeCloseFeedback LIKE CONCAT('%',#{params.noticeCloseFeedback},'%')
